/**
 * Phase 20 MatchExplanationCard Component.
 * Displays qualitative strengths and gaps generated by the backend matching engine.
 */

import { CheckCircle2, TrendingUp, AlertCircle } from 'lucide-react'
import type { MatchExplanation } from '@/types/matching'

interface MatchExplanationCardProps {
  explanation: MatchExplanation
  className?: string
}

export function MatchExplanationCard({
  explanation,
  className = '',
}: MatchExplanationCardProps) {
  const { strengths = [], gaps = [] } = explanation

  if (strengths.length === 0 && gaps.length === 0) {
    return null
  }

  return (
    <div className={`space-y-4 rounded-xl border border-border bg-card p-5 ${className}`}>
      <div className="flex items-center justify-between border-b border-border/60 pb-3">
        <div>
          <h3 className="text-base font-bold text-foreground">Match Insights</h3>
          <p className="text-xs text-muted-foreground">
            Key factors driving your match score for this position.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
        {/* Strengths */}
        {strengths.length > 0 && (
          <div className="space-y-2 p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20">
            <div className="flex items-center gap-1.5 font-semibold text-emerald-700 dark:text-emerald-400">
              <TrendingUp className="h-4 w-4" aria-hidden="true" />
              <span>Key Strengths ({strengths.length})</span>
            </div>
            <ul className="space-y-1.5 pl-1 list-none">
              {strengths.map((str, idx) => (
                <li key={`strength-${idx}`} className="flex items-start gap-1.5 text-foreground/90">
                  <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                  <span className="leading-relaxed">{str}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Gaps */}
        {gaps.length > 0 && (
          <div className="space-y-2 p-3 rounded-lg bg-amber-500/5 border border-amber-500/20">
            <div className="flex items-center gap-1.5 font-semibold text-amber-700 dark:text-amber-400">
              <AlertCircle className="h-4 w-4" aria-hidden="true" />
              <span>Qualification Gaps ({gaps.length})</span>
            </div>
            <ul className="space-y-1.5 pl-1 list-none">
              {gaps.map((gap, idx) => (
                <li key={`gap-${idx}`} className="flex items-start gap-1.5 text-foreground/90">
                  <span className="h-1.5 w-1.5 rounded-full bg-amber-500 shrink-0 mt-1.5" />
                  <span className="leading-relaxed">{gap}</span>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  )
}
